edits.find:
toast[type](finalMessage, {
  duration,
  action: undoable
    ? {
        label: translate("ra.action.undo"),
        onClick: handleUndo,
      }
    : undefined,
  onDismiss: handleExited,
  onAutoClose: handleExited,
});

edits.replace:
toast[type](finalMessage, {
  duration,
  action: undoable
    ? {
        label: translate("ra.action.undo"),
        onClick: handleUndo,
      }
    : undefined,
  onDismiss: handleExited,
  onAutoClose: handleExited,
});
window.setTimeout(() => {
  toast[type](finalMessage, { duration });
}, 300);
